begin;
create table if not exists public.data_rooms(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.opportunities(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,status text not null default 'active' check(status in('active','locked','archived')),nda_required boolean not null default true,watermark_enabled boolean not null default true,download_enabled boolean not null default false,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(opportunity_id));
create table if not exists public.data_room_members(id uuid primary key default gen_random_uuid(),data_room_id uuid not null references public.data_rooms(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,access_level text not null default 'viewer' check(access_level in('viewer','contributor','manager')),expires_at timestamptz,granted_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(data_room_id,user_id));
create table if not exists public.document_versions(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.documents(id) on delete cascade,version integer not null,storage_path text not null,checksum text,size_bytes bigint,mime_type text,uploaded_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(document_id,version));
create table if not exists public.nda_acceptances(id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.opportunities(id) on delete cascade,organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,accepted_at timestamptz not null default now(),ip_address inet,user_agent text,document_hash text,unique(opportunity_id,user_id));
create table if not exists public.workflow_events(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete set null,actor_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid not null,payload jsonb not null default '{}'::jsonb,correlation_id uuid,created_at timestamptz not null default now());
create index if not exists data_rooms_org_idx on public.data_rooms(organization_id);create index if not exists data_room_members_room_idx on public.data_room_members(data_room_id);create index if not exists data_room_members_user_idx on public.data_room_members(user_id);create index if not exists document_versions_document_idx on public.document_versions(document_id);create index if not exists nda_acceptances_opportunity_idx on public.nda_acceptances(opportunity_id);create index if not exists workflow_events_entity_idx on public.workflow_events(entity_type,entity_id,created_at desc);create index if not exists workflow_events_org_idx on public.workflow_events(organization_id,created_at desc);
alter table public.data_rooms enable row level security;alter table public.data_room_members enable row level security;alter table public.document_versions enable row level security;alter table public.nda_acceptances enable row level security;alter table public.workflow_events enable row level security;
create policy data_rooms_member_select on public.data_rooms for select to authenticated using(is_org_member(organization_id) or exists(select 1 from public.data_room_members m where m.data_room_id=id and m.user_id=(select auth.uid()) and(m.expires_at is null or m.expires_at>now())));
create policy data_rooms_owner_write on public.data_rooms for all to authenticated using(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])) with check(has_org_role(organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]));
create policy data_room_members_participant_select on public.data_room_members for select to authenticated using(user_id=(select auth.uid()) or is_org_member(organization_id));create policy data_room_members_manager_write on public.data_room_members for all to authenticated using(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role]))) with check(exists(select 1 from public.data_rooms r where r.id=data_room_id and has_org_role(r.organization_id,array['seller_admin'::member_role,'operations_admin'::member_role,'deal_manager'::member_role,'platform_admin'::member_role])));
create policy document_versions_participant_select on public.document_versions for select to authenticated using(exists(select 1 from public.documents d where d.id=document_id and is_org_member(d.organization_id)));create policy document_versions_uploader_insert on public.document_versions for insert to authenticated with check(uploaded_by=(select auth.uid()) and exists(select 1 from public.documents d where d.id=document_id and is_org_member(d.organization_id)));
create policy nda_acceptance_participant_select on public.nda_acceptances for select to authenticated using(user_id=(select auth.uid()) or is_org_member(organization_id));create policy nda_acceptance_self_insert on public.nda_acceptances for insert to authenticated with check(user_id=(select auth.uid()) and is_org_member(organization_id));
create policy workflow_events_org_select on public.workflow_events for select to authenticated using(organization_id is null or is_org_member(organization_id));create policy workflow_events_server_insert on public.workflow_events for insert to authenticated with check(actor_id=(select auth.uid()) and(organization_id is null or is_org_member(organization_id)));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('assetveyra-private','assetveyra-private',false,52428800,array['application/pdf','image/jpeg','image/png','image/webp','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']) on conflict(id) do update set public=false,file_size_limit=52428800;
commit;